+package com.example.contact;
+
+import java.util.Objects;
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(EmailValidator.PATTERN);
+
+    private final ContactMessageStore messageStore;
+    private final ContactFormState formState;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>();
+
+    private boolean resettingAfterSend;
+    private ContinueNavigationAction pendingNavigation;
+    private Dialog discardDialog;
+
+    public ContactView(ContactMessageStore messageStore, ContactFormState formState) {
+        this.messageStore = Objects.requireNonNull(messageStore);
+        this.formState = Objects.requireNonNull(formState);
+
+        setWidthFull();
+        name.setWidthFull();
+        email.setWidthFull();
+        phone.setWidthFull();
+        message.setWidthFull();
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::email).setHeader("Email");
+        messages.addColumn(ContactMessage::phone).setHeader("Phone");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setItems(messageStore.newestFirst());
+        messages.setWidthFull();
+
+        send.addClickListener(event -> sendMessage());
+        send.setEnabled(!formState.isSendDisabledAfterSend());
+        name.addValueChangeListener(event -> onEdit());
+        email.addValueChangeListener(event -> onEdit());
+        phone.addValueChangeListener(event -> onEdit());
+        message.addValueChangeListener(event -> onEdit());
+
+        // Handle real key events from each field. The UI-level shortcut below
+        // also supports shortcuts dispatched at the UI root.
+        name.addKeyDownListener(Key.ENTER, event -> sendMessage());
+        email.addKeyDownListener(Key.ENTER, event -> sendMessage());
+        phone.addKeyDownListener(Key.ENTER, event -> sendMessage());
+        message.addKeyDownListener(Key.ENTER, event -> sendMessage());
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class),
+                name, email, phone, message, send, messages);
+
+        // Keep a UI-level shortcut for Flow/browserless shortcuts. The field
+        // key listeners above handle real key events from their own elements.
+        addAttachListener(attach -> Shortcuts.addShortcutListener(this,
+                event -> sendMessage(), Key.ENTER)
+                .listenOn(attach.getUI())
+                .bindLifecycleTo(this));
+    }
+
+    private void onEdit() {
+        if (!resettingAfterSend) {
+            formState.markEdited();
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        if (!send.isEnabled()) {
+            return;
+        }
+
+        String enteredName = name.getValue();
+        String enteredEmail = email.getValue();
+        String enteredPhone = phone.getValue();
+        String enteredMessage = message.getValue();
+
+        boolean valid = true;
+
+        boolean nameMissing = enteredName == null || enteredName.isBlank();
+        name.setInvalid(nameMissing);
+        name.setErrorMessage(nameMissing ? "Name is required" : null);
+        valid &= !nameMissing;
+
+        boolean emailMissing = enteredEmail == null || enteredEmail.isBlank();
+        boolean phoneMissing = enteredPhone == null || enteredPhone.isBlank();
+        boolean emailInvalid = !emailMissing && !isValidEmail(enteredEmail);
+        String emailError = emailInvalid ? "Enter a valid e-mail address"
+                : emailMissing && phoneMissing ? "Give an e-mail address or a phone number" : null;
+        email.setInvalid(emailError != null);
+        email.setErrorMessage(emailError);
+        valid &= emailError == null;
+
+        boolean messageMissing = enteredMessage == null || enteredMessage.isBlank();
+        boolean messageTooLong = enteredMessage != null && enteredMessage.length() > 500;
+        String messageError = messageMissing ? "Message is required"
+                : messageTooLong ? "Message must be at most 500 characters" : null;
+        message.setInvalid(messageError != null);
+        message.setErrorMessage(messageError);
+        valid &= messageError == null;
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(enteredName, enteredEmail, enteredPhone, enteredMessage));
+        messages.setItems(messageStore.newestFirst());
+        Notification.show("Message sent");
+
+        resettingAfterSend = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        resettingAfterSend = false;
+        clearErrors();
+        formState.markSent();
+        send.setEnabled(false);
+    }
+
+    private void clearErrors() {
+        name.setInvalid(false);
+        name.setErrorMessage(null);
+        email.setInvalid(false);
+        email.setErrorMessage(null);
+        message.setInvalid(false);
+        message.setErrorMessage(null);
+    }
+
+    private boolean isValidEmail(String value) {
+        // EmailField's built-in validator is intentionally not enabled so that all
+        // fields can be validated together on Send with the required error text.
+        return EMAIL_PATTERN.matcher(value).matches();
+    }
+
+    private boolean hasEnteredData() {
+        return hasText(name.getValue()) || hasText(email.getValue())
+                || hasText(phone.getValue()) || hasText(message.getValue());
+    }
+
+    private boolean hasText(String value) {
+        return value != null && !value.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasEnteredData()) {
+            return;
+        }
+
+        pendingNavigation = event.postpone();
+        if (discardDialog != null && discardDialog.isOpened()) {
+            return;
+        }
+
+        discardDialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> {
+            discardDialog.close();
+            pendingNavigation.cancel();
+            pendingNavigation = null;
+        });
+        Button discard = new Button("Discard", click -> {
+            discardDialog.close();
+            ContinueNavigationAction navigation = pendingNavigation;
+            pendingNavigation = null;
+            navigation.proceed();
+        });
+        discardDialog.add(keepEditing, discard);
+        discardDialog.open();
+    }
+}
