+
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactBrowserIT extends AbstractBasePlaywrightIT {
+    @Value("${local.server.port}")
+    private int port;
+
+    @BeforeAll
+    static void startBrowser() {
+        AbstractBasePlaywrightIT.setup();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        AbstractBasePlaywrightIT.cleanup();
+    }
+
+    @BeforeEach
+    void openPage() throws Exception {
+        setupTest();
+    }
+
+    @AfterEach
+    void closePage() {
+        cleanupTest();
+    }
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void sendsAndConfirmsDiscardInChromium() {
+        var page = getPage();
+        assertEquals("Contact", page.locator("h1").textContent());
+        page.getByLabel("Name").fill("Browser Alex");
+        page.getByLabel("Phone").fill("555-0199");
+        page.getByLabel("Message").fill("Browser message");
+        page.getByLabel("Name").press("Enter");
+        page.waitForFunction("() => document.querySelector('vaadin-text-field').value === ''");
+        assertEquals("", page.getByLabel("Name").inputValue());
+        assertTrue(page.locator("vaadin-notification")
+                .evaluate("element => element.text").toString().contains("Message sent"));
+
+        page.getByLabel("Name").fill("Draft");
+        page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+        page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertEquals("Draft", page.getByLabel("Name").inputValue());
+
+        page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+        var discard = page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Discard"));
+        discard.click();
+        page.waitForFunction("() => document.querySelector('h1')?.textContent === 'About'");
+        assertEquals("About", page.locator("h1").textContent());
+    }
+}
