+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @Test
+    void validatesSendsAndGuardsNavigation() {
+        ContactView view = navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        test(name).setValue("Alex");
+        test(email).setValue("invalid");
+        test(phone).setValue("555-0100");
+        test(message).setValue("Hello");
+        test(send).click();
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals(0, $(Grid.class).single().getListDataView().getItems().count());
+        assertEquals("Alex", name.getValue());
+        assertEquals("invalid", email.getValue());
+        assertTrue($(Notification.class).all().isEmpty());
+
+        test(email).clear();
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(0, $(Grid.class).single().getListDataView().getItems().count());
+
+        test(message).setValue("Hello");
+        fireShortcut(Key.ENTER);
+        assertEquals(1, view.getChildren().filter(Grid.class::isInstance)
+                .map(Grid.class::cast).map(grid -> ((Grid<?>) grid).getListDataView().getItems().count())
+                .findFirst().orElse(0L));
+        assertFalse(send.isEnabled());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue($(Notification.class).single().getElement().getProperty("text").contains("Message sent"));
+        fireShortcut(Key.ENTER);
+        assertFalse(name.isInvalid());
+        assertFalse(email.isInvalid());
+        assertFalse(message.isInvalid());
+
+        navigate(AboutView.class);
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertTrue($(Dialog.class).all().isEmpty());
+        navigate(ContactView.class);
+        assertEquals(1, $(Grid.class).first().getListDataView().getItems().count());
+
+        Button returnedSend = $(Button.class).withText("Send").single();
+        assertFalse(returnedSend.isEnabled());
+        TextField draftName = $(TextField.class).withLabel("Name").single();
+        test(draftName).setValue("Draft");
+        assertTrue(returnedSend.isEnabled());
+        assertThrows(IllegalArgumentException.class, () -> navigate(AboutView.class));
+        assertTrue($(Dialog.class).first().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertEquals("Draft", draftName.getValue());
+        assertTrue(getCurrentView() instanceof ContactView);
+
+        assertThrows(IllegalArgumentException.class, () -> navigate(AboutView.class));
+        test($(Button.class).withText("Discard").single()).click();
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertEquals("About", $(H1.class).single().getText());
+
+        navigate(ContactView.class);
+        Grid<?> returnedGrid = $(Grid.class).first();
+        assertEquals(1, returnedGrid.getListDataView().getItems().count());
+        assertEquals("Alex", ((ContactMessage) returnedGrid.getListDataView().getItems()
+                .findFirst().orElseThrow()).name());
+    }
+}
